// CC-BY

// Scale of the hexagon grid
float S = 15.0;

// Noise repeat (how many cells on the torus)
float M = 120.0;

// Scale of the noise
float NS = 4.5;

// Set to true if you want to generate a DAG
// with false, there might be cycles.
// Also possible to have two edges going between two points
bool DAG = true;

// Jittering of the vertices in [0.0, 1.0]
float J = 0.15;

// Edge width
float W = 0.08;

// Vectors from a center hexagon
// to all it's neighbors (and neighbors' neighbors)
// You might need to check for a bigger neighnorhood
// if the jitter and edge width are both high.
// Should be at least 1. 0 will only show the start of
// the edges.
#define LAYERS 1
#if (LAYERS == 0)
# define NEIGH 1
#elif (LAYERS == 1)
# define NEIGH 7
#elif (LAYERS > 1)
# define NEIGH 19
#endif
const vec2 N_scale = vec2(1.0, sqrt(3.0) / 2.0);
const vec2 N[NEIGH] = vec2[NEIGH](
    // Center
    vec2(0.0, 0.0)

#if (NEIGH > 1)
    ,
    // First layer
    vec2( 1.0, 0.0), vec2( 0.5,  1.0), vec2(-0.5,  1.0),
    vec2(-1.0, 0.0), vec2(-0.5, -1.0), vec2( 0.5, -1.0)


#if (NEIGH > 7)
    ,
    // Second layer
    vec2( 2.0,  0.0), vec2( 1.5,  1.0), vec2( 1.0,  2.0),
    vec2( 0.0,  2.0), vec2(-1.0,  2.0), vec2(-1.5,  1.0),
    vec2(-2.0,  0.0), vec2( 1.5, -1.0), vec2( 1.0, -2.0),
    vec2( 0.0, -2.0), vec2(-1.0, -2.0), vec2(-1.5, -1.0)
#endif
#endif
);

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float mouse_clicked = clamp(iMouse.z, 0.0, 1.0);
    vec2 uv = fragCoord / iResolution.y;

    vec2 time_shift = vec2(iTime);
    time_shift.x *= iResolution.y / iResolution.x;

    // Flip the UV, looks a bit better IMO
    vec2 p = uv.yx * S + time_shift - vec2(2.0, 2.0);
    vec2 hex_center = hex(p);

    float min_dot = 1.0;
    vec3 min_hue = vec3(1.0);
    for (int i = 0; i < NEIGH; ++i) {
        vec2 start_cell = hex(hex_center + N_scale * N[i]);
        vec2 start_point = start_cell + random_in_circle(0.5, start_cell) * J;

        vec3 start_val = noised(start_cell / S * NS, M);
        vec2 start_grad = -normalize(start_val.yz);

        vec2 end_cell = hex(start_cell + start_grad);
        vec2 end_point = end_cell + random_in_circle(0.5, end_cell) * J;

        vec3 end_val = noised(end_cell / S * NS, M);

        float comparison_dot = 1.0;
        float hue_coef = 1.0;
        float t = 0.0;
        if (end_val.x < start_val.x || !DAG) {
            vec2 to_line = sdf_segment(p, start_point, end_point);
            t = distance(p + to_line, start_point) / distance(end_point, start_point);
            comparison_dot = dot(to_line, to_line) + 0.007 * sqrt(t) * mouse_clicked;
        }

        else {
            vec2 to_itself = start_point - p;
            comparison_dot = dot(to_itself, to_itself);
            hue_coef = 0.2;
        }

        if (comparison_dot < min_dot) {
            min_dot = comparison_dot;
            vec3 start_color = normalize(max(abs(hash32(start_cell)), vec3(0.01)));
            vec3 end_color = normalize(max(abs(hash32(end_cell)), vec3(0.01)));
            min_hue = mix(start_color, end_color, t) * hue_coef;
        }
    }

    float dist = sqrt(min_dot);
    float w = S / iResolution.y; // For AA, alternative to fwidth(dist)
    vec3 tree_color = mix(vec3(0.9), min_hue, mouse_clicked);

    // Background noise
    vec3 color = vec3((0.5 + 0.5 * noised(p / S * NS, M).x)) * 0.5;

    // Draw the tree on top with distance field (anti-aliased)
    color = mix(tree_color, color, smoothstep(-w, w, dist - W));

    fragColor = vec4(pow(color, vec3(1.0 / 2.2)), 1.0);
}

// https://www.shadertoy.com/view/4Xyyzw
int mod3(int n) {
    int m3 = n % 3;
    if (m3 < 0)
        m3 += 3;

    return m3;
}

// Calculate hex ID on a scaled and skewed lattice
vec2 hex(vec2 p) {
    vec2 scaled_skewed = vec2(p.x, 0.5 * (p.x + p.y * sqrt(3.0))) * 2.0;

    ivec2 rec_cell = ivec2(floor(scaled_skewed));
	vec2 rec_loc = fract(scaled_skewed);

	int m3 = mod3(rec_cell.x + rec_cell.y);

    ivec2 hex_id = rec_cell + m3;
    if (m3 == 2)
        if (rec_loc.x > rec_loc.y)
            hex_id -= ivec2(1, 2);
        else
            hex_id -= ivec2(2, 1);

    vec2 hex_id_f = vec2(hex_id);        

    return vec2(hex_id_f.x, sqrt(3.0) * (2.0 * hex_id_f.y - hex_id_f.x) / 3.0) / 2.0;
}

// https://www.shadertoy.com/view/4djSRW
vec2 hash22(vec2 p) {
    // credit to Dave_Hoskins - https://www.shadertoy.com/view/4djSRW
	vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx+33.33);
    return fract((p3.xx+p3.yz)*p3.zy);
}

// https://www.shadertoy.com/view/4djSRW
float hash12(vec2 p) {
	vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// https://www.shadertoy.com/view/4djSRW
vec3 hash32(vec2 p) {
	vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz+33.33);
    return fract((p3.xxy+p3.yzz)*p3.zyx);
}

vec2 mod_hash(vec2 x, vec2 m) {
    x = mod(x, m);
    const vec2 k = vec2(0.3183099, 0.3678794);
    x = x * k + k.yx;
    return -1.0 + 2.0 * fract(16.0 * k * fract(x.x * x.y * (x.x + x.y)));
}

vec3 noised(vec2 p, float m) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    vec2 u = f*f*f*(f*(f*6.0-15.0)+10.0);
    vec2 du = 30.0*f*f*(f*(f-2.0)+1.0);

    vec2 ga = mod_hash(i + vec2(0.0, 0.0), vec2(m));
    vec2 gb = mod_hash(i + vec2(1.0, 0.0), vec2(m));
    vec2 gc = mod_hash(i + vec2(0.0, 1.0), vec2(m));
    vec2 gd = mod_hash(i + vec2(1.0, 1.0), vec2(m));

    float va = dot(ga, f - vec2(0.0, 0.0));
    float vb = dot(gb, f - vec2(1.0, 0.0));
    float vc = dot(gc, f - vec2(0.0, 1.0));
    float vd = dot(gd, f - vec2(1.0, 1.0));

    return vec3(va + u.x*(vb-va) + u.y*(vc-va) + u.x*u.y*(va-vb-vc+vd),
        		ga + u.x*(gb-ga) + u.y*(gc-ga) + u.x*u.y*(ga-gb-gc+gd) +
        		du * (u.yx*(va-vb-vc+vd) + vec2(vb,vc) - va));
}

vec2 sdf_segment(vec2 p, vec2 start, vec2 end) {
	vec2 sp = p - start;
	vec2 se = end - start;
	float dist = clamp(dot(sp, se) / dot(se, se), 0.0, 1.0);
	vec2 to_line = se * dist - sp;
	return to_line;
}

vec2 random_in_circle(float r, vec2 seed) {
    float a = hash12(seed);
    float b = hash12(a * seed);
    float R = sqrt(a) * r;
    float A = 6.283 * b;
    return R * vec2(cos(A), sin(A));
}
